'use strict';
// Stand-in for the Salesforce CLI's @salesforce/core: Org.create + a connection
// whose request() renews its own token on 401 and travels the CLI's route
// (x-fake-cli), like jsforce inside the real CLI.
const http = require('http');
const USERS = { 'dev@example.com': 1, 'uat@example.com': 1, 'prod@example.com': 1, uat: 'uat@example.com' };
const stats = global.__fakeCore = global.__fakeCore || { creates: 0, requests: 0, renewals: 0 };

function call(method, url, body, token) {
  return new Promise((resolve, reject) => {
    const u = new URL(url, process.env.FAKE_SF_INSTANCE);
    const req = http.request(u, { method, headers: Object.assign({ Authorization: 'Bearer ' + token, 'x-fake-cli': '1' }, body ? { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) } : {}) }, res => {
      let b = ''; res.on('data', d => { b += d; }); res.on('end', () => resolve({ status: res.statusCode, text: b }));
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

class Connection {
  constructor(username, version) { this.username = username; this.version = version || '61.0'; this.instanceUrl = process.env.FAKE_SF_INSTANCE; this.token = 'stale'; }
  async request(opts) {
    stats.requests++;
    let r = await call(opts.method, opts.url, opts.body, this.token);
    if (r.status === 401) { stats.renewals++; this.token = JSON.parse((await call('GET', '/__token', null, '')).text).token; r = await call(opts.method, opts.url, opts.body, this.token); }
    const json = r.text ? JSON.parse(r.text) : null;
    if (r.status >= 400) { const f = Array.isArray(json) ? json[0] : json || {}; const e = new Error(f.message || 'HTTP ' + r.status); e.errorCode = f.errorCode; e.name = f.errorCode || 'Error'; e.statusCode = r.status; throw e; }
    return json;
  }
}

class Org {
  static async create({ aliasOrUsername }) {
    stats.creates++;
    const u = typeof USERS[aliasOrUsername] === 'string' ? USERS[aliasOrUsername] : USERS[aliasOrUsername] ? aliasOrUsername : null;
    if (!u) throw new Error('No authorization information found for ' + aliasOrUsername + '.');
    return Object.assign(new Org(), { username: u });
  }
  getConnection(version) { return new Connection(this.username, version); }
}

module.exports = { Org, Connection };
